#!/usr/bin/env python3
"""Mechanical constructor-token comparison of solution.mpy and entry claims."""

from __future__ import annotations

import re
from pathlib import Path


def balanced_module_terms(text: str) -> list[str]:
    terms: list[str] = []
    start = 0
    while True:
        start = text.find("Module(", start)
        if start < 0:
            return terms
        depth = 0
        in_string = False
        escaped = False
        for index in range(start, len(text)):
            character = text[index]
            if in_string:
                if escaped:
                    escaped = False
                elif character == "\\":
                    escaped = True
                elif character == '"':
                    in_string = False
                continue
            if character == '"':
                in_string = True
            elif character == "(":
                depth += 1
            elif character == ")":
                depth -= 1
                if depth == 0:
                    terms.append(text[start : index + 1])
                    start = index + 1
                    break
        else:
            raise ValueError(f"unbalanced Module term beginning at offset {start}")


token_pattern = re.compile(
    r'"(?:\\.|[^"\\])*"|'
    r"-?[0-9]+|"
    r"[A-Za-z_][A-Za-z_0-9-]*|"
    r"[(),]"
)


def tokens(term: str) -> list[str]:
    parsed = token_pattern.findall(term)
    residue = token_pattern.sub("", term)
    if residue.strip():
        raise ValueError(f"unexpected constructor-term text: {residue!r}")
    return parsed


